solution.solution.cpp:
#include <cctype>
#include <cstdint>
#include <string>
#include <vector>

struct FileVersion { uint32_t ms{ 0 }; uint32_t ls{ 0 }; };

bool parseFileVersion(const std::string& text, FileVersion& out)
{
    std::vector<uint32_t> parts;
    std::string current;
    for (std::size_t i{ 0 }; i <= text.size(); ++i)
    {
        if (i == text.size() || text[i] == '.')
        {
            if (current.empty() || current.size() > 5) return false;
            const unsigned long value{ std::stoul(current) };
            if (value > 65535) return false;
            parts.push_back(static_cast<uint32_t>(value));
            current.clear();
        }
        else if (std::isdigit(static_cast<unsigned char>(text[i]))) current += text[i];
        else return false;
    }
    if (parts.empty() || parts.size() > 4) return false;
    parts.resize(4, 0);
    out.ms = parts[0] << 16 | parts[1];
    out.ls = parts[2] << 16 | parts[3];
    return true;
}

std::string formatFileVersion(const FileVersion& v)
{
    return std::to_string(v.ms >> 16) + "." + std::to_string(v.ms & 0xFFFF) + "." + std::to_string(v.ls >> 16) + "." + std::to_string(v.ls & 0xFFFF);
}

bool isNewer(const FileVersion& candidate, const FileVersion& installed)
{
    if (candidate.ms != installed.ms) return candidate.ms > installed.ms;
    return candidate.ls > installed.ls;
}

unitTests:
FileVersion F(const char* s) { FileVersion v; parseFileVersion(s, v); return v; }
TEST("parse four parts") { FileVersion v; CHECK(parseFileVersion("2.4.1.0", v)); CHECK_EQ(v.ms, (2u << 16) | 4u); CHECK_EQ(v.ls, (1u << 16) | 0u); }
TEST("missing parts are zero") { CHECK_EQ(formatFileVersion(F("2.4")), std::string("2.4.0.0")); CHECK_EQ(formatFileVersion(F("7")), std::string("7.0.0.0")); }
TEST("largest parts") { CHECK_EQ(formatFileVersion(F("65535.0.65535.1")), std::string("65535.0.65535.1")); }
TEST("rejects") { FileVersion v; CHECK(!parseFileVersion("", v)); CHECK(!parseFileVersion("1.2.3.4.5", v)); CHECK(!parseFileVersion("1..2", v)); CHECK(!parseFileVersion("1.65536", v)); CHECK(!parseFileVersion("1.x", v)); CHECK(!parseFileVersion("1.2.", v)); }
TEST("newer") { CHECK(isNewer(F("2.4.1.0"), F("2.4.0.9"))); CHECK(isNewer(F("2.10"), F("2.9.999"))); CHECK(!isNewer(F("2.4.1.0"), F("2.4.1.0"))); CHECK(!isNewer(F("1.99"), F("2.0"))); }

